"use client"

import { useMemo } from "react"
import Image from "next/image"
import Link from "next/link"
import { motion, AnimatePresence } from "framer-motion"
import { Trash2, Plus, Minus, ShoppingBag, ArrowRight, Coins } from "lucide-react"
import { useAppStore } from "@/lib/store/app-store"
import { usePoints } from "@/lib/store/points-context"
import { Button } from "@/components/ui/button"
import { AnimatedCounter } from "@/components/ui/animated-counter"
import { cn } from "@/lib/utils"

// Nueva equivalencia: 25 puntos = $2.00
const POINTS_TO_DOLLAR_RATE = 2.00 / 25 // $0.08 por punto
const POINTS_STEP = 25 // Incremento mínimo de 25 puntos

export function CartView() {
  const { state, dispatch } = useAppStore()
  const { points, usePoints: spendPoints, addPoints: addUserPoints } = usePoints()

  const subtotal = useMemo(() => {
    return state.cart.reduce((sum, item) => sum + item.total_price, 0)
  }, [state.cart])

  // Puntos usados en todo el carrito
  const points_used_in_cart = useMemo(() => {
    return state.cart.reduce((sum, item) => sum + (item.points_used || 0), 0)
  }, [state.cart])

  // Puntos disponibles para nuevos ítems
  const available_points = points - points_used_in_cart

  const handleRemoveItem = async (itemId: string) => {
    const item = state.cart.find(item => item.id === itemId)
    if (item?.points_used && item.points_used > 0) {
      // Devolver los puntos al usuario
      await addUserPoints(item.points_used, `Puntos devueltos de: ${item.pizza.name}`)
    }
    dispatch({ type: "REMOVE_FROM_CART", payload: itemId })
  }

  const handleUpdateQuantity = (itemId: string, newQuantity: number) => {
    if (newQuantity <= 0) {
      handleRemoveItem(itemId)
    } else {
      dispatch({ type: "UPDATE_CART_ITEM", payload: { id: itemId, quantity: newQuantity } })
    }
  }

  const calculateDiscountFromPoints = (pointsUsed: number) => {
    return pointsUsed * POINTS_TO_DOLLAR_RATE
  }

  const getAvailablePointsForItem = (itemId: string, currentItemPoints: number) => {
    const otherItemsPoints = state.cart.reduce((sum, cartItem) => {
      if (cartItem.id !== itemId) return sum + (cartItem.points_used || 0)
      return sum
    }, 0)
    
    return Math.max(0, points - otherItemsPoints + currentItemPoints)
  }

  const getMaxPointsForItem = (itemTotalPrice: number, itemId: string, currentItemPoints: number) => {
    const availableForItem = getAvailablePointsForItem(itemId, currentItemPoints)
    const maxPointsByPrice = Math.floor(itemTotalPrice / POINTS_TO_DOLLAR_RATE)
    
    return Math.min(maxPointsByPrice, Math.max(0, availableForItem))
  }

  const handleIncrementPoints = async (itemId: string) => {
    const item = state.cart.find(item => item.id === itemId)
    if (!item) return
    
    const currentPoints = item.points_used || 0
    const maxPoints = getMaxPointsForItem(item.total_price, itemId, currentPoints)
    
    if (currentPoints + POINTS_STEP <= maxPoints) {
      // Usar puntos
      const success = await spendPoints(POINTS_STEP, `Puntos usados para: ${item.pizza.name}`)
      if (success) {
        dispatch({ 
          type: "UPDATE_CART_ITEM_POINTS", 
          payload: { id: itemId, points_used: currentPoints + POINTS_STEP } 
        })
      }
    }
  }

  const handleDecrementPoints = async (itemId: string) => {
    const item = state.cart.find(item => item.id === itemId)
    if (!item) return
    
    const currentPoints = item.points_used || 0
    
    if (currentPoints - POINTS_STEP >= 0) {
      // Devolver puntos
      await addUserPoints(POINTS_STEP, `Puntos devueltos de: ${item.pizza.name}`)
      dispatch({ 
        type: "UPDATE_CART_ITEM_POINTS", 
        payload: { id: itemId, points_used: currentPoints - POINTS_STEP } 
      })
    }
  }

  if (state.cart.length === 0) {
    return (
      <div className="min-h-[60vh] flex flex-col items-center justify-center text-center px-4">
        <motion.div
          initial={{ scale: 0.8, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ type: "spring", damping: 20 }}
        >
          <ShoppingBag className="h-24 w-24 text-muted-foreground/30 mb-6" />
        </motion.div>
        <h2 className="font-serif text-2xl font-bold text-foreground mb-2">Tu carrito está vacío</h2>
        <p className="text-muted-foreground mb-6">Agrega deliciosas pizzas para comenzar</p>
        <Link href="/menu">
          <Button className="bg-primary hover:bg-primary/90">
            Ver Menú
            <ArrowRight className="ml-2 h-4 w-4" />
          </Button>
        </Link>
      </div>
    )
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <motion.h1
        initial={{ y: 20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="font-serif text-3xl font-bold text-foreground mb-8"
      >
        Tu Carrito
      </motion.h1>

      <div className="grid lg:grid-cols-3 gap-8">
        {/* Cart Items */}
        <div className="lg:col-span-2 space-y-4">
          <AnimatePresence mode="popLayout">
            {state.cart.map((item, index) => {
              const currentPoints = item.points_used || 0
              const itemDiscount = calculateDiscountFromPoints(currentPoints)
              const itemFinalPrice = Math.max(0, item.total_price - itemDiscount)
              const maxPoints = getMaxPointsForItem(item.total_price, item.id, currentPoints)
              const canIncrement = currentPoints + POINTS_STEP <= maxPoints
              const canDecrement = currentPoints - POINTS_STEP >= 0
              const canUsePoints = maxPoints >= POINTS_STEP

              return (
                <motion.div
                  key={item.id}
                  layout
                  initial={{ x: -20, opacity: 0 }}
                  animate={{ x: 0, opacity: 1 }}
                  exit={{ x: 20, opacity: 0 }}
                  transition={{ delay: index * 0.05 }}
                  className="flex flex-col gap-4 p-4 rounded-xl bg-card border border-border"
                >
                  <div className="flex gap-4">
                    <div className="relative w-24 h-24 rounded-lg overflow-hidden flex-shrink-0">
                      <Image
                        src={item.pizza.image || "/placeholder.svg"}
                        alt={item.pizza.name}
                        fill
                        className="object-cover"
                      />
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between">
                        <div>
                          <h3 className="font-semibold text-foreground truncate">{item.pizza.name}</h3>
                          {item.selected_toppings.length > 0 && (
                            <p className="text-sm text-muted-foreground">
                              <span className="text-primary font-medium">+ Extra: </span>
                              {item.selected_toppings.map((t) => t.name).join(", ")}
                            </p>
                          )}
                        </div>
                        <div className="flex flex-col items-end">
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-muted-foreground hover:text-destructive"
                            onClick={() => handleRemoveItem(item.id)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                          
                          <div className="flex items-center gap-2 mt-2">
                            <Button
                              variant="outline"
                              size="icon"
                              className="h-8 w-8 bg-transparent"
                              onClick={() => handleUpdateQuantity(item.id, item.quantity - 1)}
                            >
                              <Minus className="h-3 w-3" />
                            </Button>
                            <span className="w-8 text-center font-medium">{item.quantity}</span>
                            <Button
                              variant="outline"
                              size="icon"
                              className="h-8 w-8 bg-transparent"
                              onClick={() => handleUpdateQuantity(item.id, item.quantity + 1)}
                            >
                              <Plus className="h-3 w-3" />
                            </Button>
                          </div>
                        </div>
                      </div>
                      
                      <div className="mt-4">
                        <p className="text-lg font-bold text-primary">
                          ${itemFinalPrice.toFixed(2)}
                          {currentPoints > 0 && (
                            <span className="text-sm text-green-600 ml-2">
                              (Ahorro: ${itemDiscount.toFixed(2)})
                            </span>
                          )}
                        </p>
                      </div>
                    </div>
                  </div>

                  {/* Points Discount Section for each item */}
                  <div className={cn(
                    "rounded-lg p-4 border transition-all",
                    canUsePoints 
                      ? "bg-secondary/10 border-secondary/30" 
                      : "bg-muted/30 border-muted"
                  )}>
                    <div className="flex items-center gap-2 mb-4">
                      <Coins className={cn(
                        "h-5 w-5",
                        canUsePoints ? "text-secondary" : "text-muted-foreground"
                      )} />
                      <div>
                        <h4 className={cn(
                          "font-medium",
                          canUsePoints ? "text-foreground" : "text-muted-foreground"
                        )}>
                          Usar puntos para este ítem
                        </h4>
                        <p className="text-xs text-muted-foreground mt-1">
                          25 puntos = $2.00 de descuento
                        </p>
                      </div>
                    </div>
                    
                    {canUsePoints ? (
                      <div className="flex items-center justify-between">
                        <div className="space-y-1">
                          <p className="text-sm text-muted-foreground">
                            Puntos disponibles para este ítem: {getAvailablePointsForItem(item.id, currentPoints)}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            Descuento máximo: ${calculateDiscountFromPoints(maxPoints).toFixed(2)}
                          </p>
                        </div>
                        
                        <div className="flex flex-col items-end space-y-2">
                          <div className="flex items-center gap-2">
                            <span className="text-sm text-muted-foreground mr-2">Puntos:</span>
                            <Button
                              variant="outline"
                              size="icon"
                              className={cn(
                                "h-8 w-8 bg-transparent",
                                !canDecrement && "opacity-50 cursor-not-allowed"
                              )}
                              onClick={() => handleDecrementPoints(item.id)}
                              disabled={!canDecrement}
                            >
                              <Minus className="h-3 w-3" />
                            </Button>
                            <div className="flex flex-col items-center min-w-[80px]">
                              <span className="w-full text-center font-medium text-lg">
                                {currentPoints}
                              </span>
                              <span className="text-xs text-green-600">
                                (${calculateDiscountFromPoints(currentPoints).toFixed(2)})
                              </span>
                            </div>
                            <Button
                              variant="outline"
                              size="icon"
                              className={cn(
                                "h-8 w-8 bg-transparent",
                                !canIncrement && "opacity-50 cursor-not-allowed"
                              )}
                              onClick={() => handleIncrementPoints(item.id)}
                              disabled={!canIncrement}
                            >
                              <Plus className="h-3 w-3" />
                            </Button>
                          </div>
                          
                          {/* Barra visual de progreso */}
                          <div className="w-full max-w-[200px]">
                            <div className="flex justify-between mb-1">
                              <span className="text-xs text-muted-foreground">0</span>
                              <span className="text-xs font-medium text-green-600">
                                ${calculateDiscountFromPoints(currentPoints).toFixed(2)}
                              </span>
                              <span className="text-xs text-muted-foreground">
                                ${calculateDiscountFromPoints(maxPoints).toFixed(2)}
                              </span>
                            </div>
                            <div className="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700">
                              <div 
                                className="bg-green-600 h-2.5 rounded-full transition-all duration-300" 
                                style={{ width: `${maxPoints > 0 ? (currentPoints / maxPoints) * 100 : 0}%` }}
                              ></div>
                            </div>
                          </div>
                        </div>
                      </div>
                    ) : (
                      <p className="text-sm text-muted-foreground">
                        No hay suficientes puntos disponibles para descuento en este ítem
                      </p>
                    )}
                  </div>
                </motion.div>
              )
            })}
          </AnimatePresence>
        </div>

        {/* Order Summary */}
        <div className="lg:col-span-1">
          <motion.div
            initial={{ y: 20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ delay: 0.2 }}
            className="sticky top-24 rounded-xl bg-card border border-border p-6"
          >
            <h2 className="font-serif text-xl font-bold text-foreground mb-6">Resumen del Pedido</h2>

            {/* Items List */}
            <div className="space-y-3 mb-4">
              {state.cart.map((item) => {
                const itemDiscount = calculateDiscountFromPoints(item.points_used || 0)
                const itemFinalPrice = Math.max(0, item.total_price - itemDiscount)
                
                return (
                  <div key={item.id} className="text-sm">
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">
                        {item.quantity}x {item.pizza.name}
                      </span>
                      <div className="text-right">
                        <span>${itemFinalPrice.toFixed(2)}</span>
                        {(item.points_used || 0) > 0 && (
                          <div className="text-xs text-green-600">
                            -${itemDiscount.toFixed(2)} con {item.points_used} puntos
                          </div>
                        )}
                      </div>
                    </div>
                    {item.selected_toppings.length > 0 && (
                      <p className="text-xs text-primary ml-4">+ {item.selected_toppings.map((t) => t.name).join(", ")}</p>
                    )}
                  </div>
                )
              })}
            </div>

            {/* Points Summary */}
            <div className="mb-4 p-3 rounded-lg bg-secondary/10 border border-secondary/30">
              <div className="flex items-center gap-2 mb-2">
                <Coins className="h-4 w-4 text-secondary" />
                <h3 className="text-sm font-medium text-secondary-foreground">Resumen de Puntos</h3>
              </div>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Puntos totales disponibles:</span>
                  <span className="font-medium">{points} puntos</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Puntos siendo usados:</span>
                  <span className="font-medium text-green-600">
                    {points_used_in_cart} puntos
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Descuento total:</span>
                  <span className="font-medium text-green-600">
                    ${calculateDiscountFromPoints(points_used_in_cart).toFixed(2)}
                  </span>
                </div>
                <div className="text-xs text-muted-foreground pt-1 border-t border-border/30">
                  25 puntos = $2.00 de descuento
                </div>
              </div>
            </div>

            {/* Totals */}
            <div className="space-y-3 border-t border-border pt-4">
              <div className="flex justify-between text-sm">
                <span className="text-muted-foreground">Subtotal</span>
                <span className="font-medium">${subtotal.toFixed(2)}</span>
              </div>
              
              <div className="flex justify-between text-sm text-green-600">
                <span>Descuento por Puntos</span>
                <span>
                  -${calculateDiscountFromPoints(points_used_in_cart).toFixed(2)}
                </span>
              </div>

              <div className="flex justify-between text-lg font-bold pt-2 border-t border-border">
                <span>Total</span>
                <AnimatedCounter 
                  value={subtotal - calculateDiscountFromPoints(points_used_in_cart)} 
                  prefix="$" 
                  className="text-primary" 
                />
              </div>
            </div>

            <Link href="/checkout">
              <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} className="mt-6">
                <Button className="w-full h-12 text-base font-semibold bg-primary hover:bg-primary/90">
                  Proceder al Pago
                  <ArrowRight className="ml-2 h-4 w-4" />
                </Button>
              </motion.div>
            </Link>

            <div className="mt-4 p-3 rounded-lg bg-secondary/10 border border-secondary/30">
              <div className="flex items-center gap-2 mb-1">
                <Coins className="h-4 w-4 text-secondary" />
                <span className="text-sm text-secondary-foreground">
                  Tienes {points} puntos disponibles
                </span>
              </div>
              <p className="text-xs text-muted-foreground">
                25 puntos = $2.00 de descuento • 1 punto = $0.08
              </p>
            </div>
          </motion.div>
        </div>
      </div>
    </div>
  )
}